const GREETING = `≡ƒæï Ryngo AI par aapka swagat hai!\n\nMain aapki help kar sakta hoon Maharashtra me kahi ka bhi **Fare calculation** karne me ya gadi book karne me. **Bolo bhai, kaise help karu?** Γ£¿`;

function parseMarkdown(text: string): string {
  return text
    .replace(/\*\*(.*?)\*\*/g, "<strong>$1</strong>")
    .replace(/\*(.*?)\*/g, "<em>$1</em>")
    .replace(/\n/g, "<br/>");
}

export default function AIChatBot() {
