    { id: "greeting", role: "assistant", text: GREETING, timestamp: new Date(2024, 0, 1) },
  ]);
  const [input, setInput] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [isMinimized, setIsMinimized] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState<string | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const recognitionRef = useRef<any>(null);

  const scrollToBottom = useCallback(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, []);

  useEffect(() => {
    if (isOpen) scrollToBottom();
  }, [isOpen, messages, scrollToBottom]);

  // --- VOICE ENGINE ---
  const toggleListening = useCallback(() => {
    if (isListening) { recognitionRef.current?.stop(); setIsListening(false); return; }
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) return;
    try {
      const recognition = new SpeechRecognition();
      recognitionRef.current = recognition;
      recognition.lang = "hi-IN";
      recognition.onstart = () => setIsListening(true);
      recognition.onend = () => setIsListening(false);
      recognition.onresult = (event: any) => {
        let transcript = "";
        for (let i = event.resultIndex; i < event.results.length; ++i) {
          if (event.results[i].isFinal) transcript += event.results[i][0].transcript;
        }
        if (transcript) setInput((p) => p + (p ? " " : "") + transcript);
      };
      recognition.start();
    } catch (err) { setIsListening(false); }
  }, [isListening]);

  const handleSpeak = (id: string, text: string) => {
    if (isSpeaking === id) { window.speechSynthesis.cancel(); setIsSpeaking(null); return; }
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text.replace(/[*#]/g, ""));
    const voices = window.speechSynthesis.getVoices();
    const desi = voices.find(v => v.lang.startsWith('hi-') || v.lang.startsWith('en-IN'));
    if (desi) utterance.voice = desi;
    else utterance.lang = "hi-IN";
    utterance.onstart = () => setIsSpeaking(id);
    utterance.onend = () => setIsSpeaking(null);
    window.speechSynthesis.speak(utterance);
  };

  // --- UNIVERSAL OMNISCIENT ENGINE + XL/PRIME ---
  const getFallbackResponse = (userInput: string) => {
    const q = userInput.toLowerCase();

    // 1) Ride Booking
    if (q.includes("book") || q.includes("time") || q.includes("cancel") || q.includes("advance") || q.includes("airport")) {
      if (q.includes("airport")) return "Bhai, Ryngo se Airport (T1/T2) drop ekdum aasan hai. Pre-book bhi kar sakte hain taaki flight miss na ho! ≡ƒ¢½";
      if (q.includes("time") || q.includes("duration")) return "Ride aane ka samay driver ki doori par nirbhar karta hai. ╨₧╨▒╤ï╤ç╨╜╨╛ 5-10 mins me cab pahunch jati hai. ΓÅ│";
      if (q.includes("cancel")) return "Bhai, agar aap booking ke 5 min baad cancel karte hain, toh thoda charge lag sakta hai driver ke time ke liye. ≡ƒ¢æ";
      return "Steps:\n1. Pickup-Drop address bhariye.\n2. 'Request Now' dabaiye.\n3. Apni gadi Select kijiye aur booking ho gayi! Γ£àΓ£¿";
    }

    // 2) Mumbai Specific Routes
    if (q.includes("mumbai") || q.includes("bkc") || q.includes("traffic") || q.includes("highway") || q.includes("marine drive") || q.includes("andheri") || q.includes("powai")) {
      if (q.includes("bkc")) return "BKC ke liye hamare paas special corporate-friendly rides hain. Traffic ke hisaab se hum fastest route suggest karenge! ≡ƒÅó≡ƒ¢ú∩╕Å";
      if (q.includes("traffic") || q.includes("highway")) return "Mumbai traffic ka toh pata hi hai bhai! Western Express Highway pe aksar heavy traffic hota hai, isliye thoda buffer time leke chalein. ≡ƒÜù≡ƒÜò≡ƒÜÖ";
      return "Main Mumbai routes ka expert hoon. BKC, Marine Drive, ya Airport - batayiye kahan jana hai? ≡ƒÅÖ∩╕Å";
    }

    // 3) Safety
    if (q.includes("safe") || q.includes("safety") || q.includes("sos") || q.includes("night") || q.includes("family") || q.includes("verify")) {
      if (q.includes("sos") || q.includes("emergency")) return "Humare app me red color ka SOS button hai, jo turant emergency team ko alert kar deta hai. ≡ƒ¢í∩╕Å≡ƒåÿ";
      if (q.includes("night")) return "Bilkul safe hai! Humari late-night rides 24/7 monitored hoti hain aur saare drivers verified hote hain. ≡ƒîÖΓ£¿";
      if (q.includes("share") || q.includes("family")) return "Aap apni ride ki live location family ke saath turant share kar sakte hain 'Share Trip' feature se. ≡ƒô▒≡ƒæ¿ΓÇì≡ƒæ⌐ΓÇì≡ƒæºΓÇì≡ƒæª";
      return "Bhai, Ryngo hamesha background-verified drivers aur GPS-tracked safe rides deta hai. Humare app me SOS feature hamesha haazir hai. ≡ƒ¢í∩╕ÅΓ£¿";
    }

    // 4) Fare & Payments
    const isFareQuery = q.includes("fare") || q.includes("kitna") || q.includes("kiraya") || q.includes("charge") || q.includes("money") || q.includes("paisa") || q.includes("cash") || q.includes("upi") || q.includes("pay");
    if (isFareQuery) {
      if (q.includes("cash") || q.includes("upi") || q.includes("paytm")) return "Haan bhai, Cash, UPI (GPay/PhonePe), aur Paytm sab chalta hai Ryngo me! ≡ƒÆ│≡ƒô▒";
      if (distance > 0) {
        const mini = Math.floor(distance * 22.7 + 40);
        const sedan = Math.floor(distance * 25.7 + 80);
        const xl = Math.floor(distance * 32 + 150);
        const primeLow = Math.floor(distance * 22.7 + 100);
        const primeHigh = Math.floor(distance * 32 + 100);

        let response = `Nakshe par trip ki doori **${distance.toFixed(1)} km** hai. Iska estimated fare:\n\n`;
        response += `- **Mini/Taxi**: Γé╣${mini}\n`;
        response += `- **Sedan**: Γé╣${sedan}\n`;
        response += `- **XL (SUV)**: Γé╣${xl}\n`;
        response += `- **Prime**: Γé╣${primeLow} - Γé╣${primeHigh}\n\n`;
        response += `Peak hours ya night (11 PM-5 AM) me rates badh sakte hain. Γ£¿≡ƒÜò`;
        return response;
