    }

    // 5) Driver Related
    if (q.includes("driver") || q.includes("call") || q.includes("complaint") || q.includes("rating")) {
      if (q.includes("call")) return "Aap app se directly driver ko call kar sakte hain. Agar woh nahi utha rahe, toh thoda wait kijiye ya support me bataiye. ≡ƒô₧";
