                              {feature}
                            </span>
                          </li>
                        ))}
                      </ul>
                    </div>

                    {/* CTA button */}
                    <button
                      className={`w-full min-h-[40px] py-2 rounded-xl font-black text-xs transition-all duration-300 active:scale-[0.97] ${
                        service.isPremium
                          ? "bg-white text-[#0B4619] hover:bg-[#FFF2C6]"
